import random
from typing import List

# Data type: arbitrary binary data
# Target stub expects FUZZ_PARAM_STR to provide a non-empty buffer (1..4096 bytes).
# The function under test xsk_umem__get_data just returns base + addr, so any
# arbitrary bytes are valid. We'll generate diverse, interesting byte patterns
# and lengths to exercise pointer arithmetic across various offsets.

MAX_SIZE = 4096
MIN_SIZE = 1

def _biased_lengths(rng: random.Random) -> List[int]:
    # Provide a set of candidate lengths to choose from, covering powers of two,
    # common frame sizes, edge cases, and random picks.
    fixed = [
        1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64,
        127, 128, 255, 256, 512, 1024, 1500, 1536, 2048, 3072, 4095, 4096,
    ]
    # Filter to valid bounds
    fixed = [x for x in fixed if MIN_SIZE <= x <= MAX_SIZE]
    # Add a few random lengths skewed towards small and large ends
    res = set(fixed)
    for _ in range(8):
        res.add(rng.randint(MIN_SIZE, MAX_SIZE))
    # Bias to include more small and page-like sizes
    res.update({rng.randint(1, 64), rng.randint(1, 128), 4096})
    lst = sorted(res)
    return lst

def _pattern_bytes(pattern: str, length: int, rng: random.Random) -> bytes:
    if pattern == "zeros":
        return bytes([0]) * length
    if pattern == "ones":
        return bytes([0xFF]) * length
    if pattern == "inc":
        start = rng.randrange(256)
        return bytes((start + i) & 0xFF for i in range(length))
    if pattern == "dec":
        start = rng.randrange(256)
        return bytes((start - i) & 0xFF for i in range(length))
    if pattern == "alt01":
        return bytes((i & 1) for i in range(length))
    if pattern == "altff00":
        return bytes(0xFF if (i & 1) == 0 else 0x00 for i in range(length))
    if pattern == "saw16":
        return bytes(i & 0xFF for i in range(length))
    if pattern == "rand":
        return rng.randbytes(length)
    if pattern == "blocks":
        # Create repeating blocks of common sizes
        block_sizes = [64, 128, 256]
        bsz = block_sizes[rng.randrange(len(block_sizes))]
        block = rng.randbytes(bsz)
        reps = (length + bsz - 1) // bsz
        data = (block * reps)[:length]
        return data
    if pattern == "edge_mix":
        # Mix of zeros, ones and random in segments
        segs = []
        remaining = length
        while remaining > 0:
            seg_len = min(1 + rng.randint(0, max(1, length // 8)), remaining)
            choice = rng.choice(["zeros","ones","rand"]) 
            segs.append(_pattern_bytes(choice, seg_len, rng))
            remaining -= seg_len
        return b"".join(segs)
    return rng.randbytes(length)

def _choose_pattern(rng: random.Random) -> str:
    patterns = [
        "zeros", "ones", "inc", "dec", "alt01", "altff00",
        "saw16", "rand", "blocks", "edge_mix",
    ]
    # Weight random and mixed patterns a bit higher
    weights = [5,5,8,6,4,4,6,12,8,10]
    return rng.choices(patterns, weights=weights, k=1)[0]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Select a length with bias
    candidates = _biased_lengths(rng)
    length = rng.choice(candidates)
    # Ensure within bounds
    length = max(MIN_SIZE, min(MAX_SIZE, length))
    # Select and build a pattern
    pattern = _choose_pattern(rng)
    data = _pattern_bytes(pattern, length, rng)
    # Ensure non-empty and bytes type
    if not data:
        data = b"\x00"
    return data
